def extend(page: str) -> str:
    page = page.replace("</style>", CSS + "</style>", 1)
    nav = ('<a href="#research" data-view="research"><span class="nav-icon" '
           'aria-hidden="true">' + icon("analysis") + '</span>Google 研究</a>')
    marker = '<a href="#analysis" data-view="analysis">'
    if marker in page:
        page = page.replace(marker, nav + marker, 1)
    page = page.replace(
        '<footer class="foot" id="updated">',
        SECTION.replace("__REFRESH__", icon("refresh"))
        + '<footer class="foot" id="updated">',
        1,
    )
    old_views = "['overview','create','tasks','results','whale','settings','analysis','monitors','api']"
    new_views = old_views[:-1] + ",'research']"
    page = page.replace(old_views, new_views)
    page = page.replace(
        "analysis:'搜索分析',monitors:'关键词监测'",
        "analysis:'搜索分析',research:'Google 研究',monitors:'关键词监测'",
        1,
    )
    page = page.replace(
        "analysis:'从历史结果中找到变化',monitors:",
        "analysis:'从历史结果中找到变化',research:'固定观测集、证据与确定性产出',monitors:",
        1,
    )
    marker = "window.addEventListener('hashchange',showView);showView();setInterval(refreshView,10000);"
    page = page.replace(marker, JS + "\n" + marker, 1)
    return page
